path, work = tmp_path / "ledger.json", tmp_path / "provider.jsonl" middleware = _middleware(path) intent = _intent(middleware) if after_work: assert middleware.admit_provider_intent_safe(intent) _physical_work(work, intent.obligation_id) observed = _record(owner_epoch=intent.owner_epoch) actual_fsync, actual_replace = module.os.fsync, module.os.replace replaced = False
def fsync(fd): if fault == "fsync" or (fault == "directory" and replaced): raise OSError("actual fsync refusal") return actual_fsync(fd)
